from collections import deque

def dist(g, start, goal):
    seen = {start}
    q = deque([(start, 0)])
    while q:
        node, d = q.popleft()
        if node == goal:
            return d
        for nb in g[node]:
            if nb not in seen:
                seen.add(nb)
                q.append((nb, d+1))
    return -1

